{
  "predictors": [
    {
      "name": "Sustainability Investment Ratio",
      "construction": "Divide the dollar amount spent on sustainability initiatives (from corporate responsibility reports) by total assets, updated annually.",
      "rationale": "Firms investing in sustainability may capture long-term growth opportunities not yet priced by the market.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Management Innovation Score",
      "construction": "Score companies based on the number of patents filed by management over the past 5 years, scaled by the number of executives.",
      "rationale": "Innovative management may lead to strategic advantages and higher future cash flows.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Social Media Sentiment Index",
      "construction": "Aggregate positive sentiment scores from major social media platforms over the past 12 months, normalized by volume.",
      "rationale": "Public perception on social media may precede formal analyst ratings, offering early signals of firm prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Satisfaction Ratio",
      "construction": "Divide the average employee satisfaction score (from surveys) by industry average, updated annually.",
      "rationale": "Higher employee satisfaction can lead to improved operational performance and innovation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Efficiency Score",
      "construction": "Calculate the ratio of cost savings from supply chain improvements over total sales, monitored semi-annually.",
      "rationale": "Efficient supply chains suggest superior management and cost control, potentially leading to higher margins.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Retention Rate",
      "construction": "Ratio of repeat customers to total customers over the past three years, using customer loyalty programs data.",
      "rationale": "A high retention rate suggests a stable revenue base and strong customer relationships.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D Tax Credit Utilization",
      "construction": "The ratio of R&D tax credits claimed to total R&D expenses over the last fiscal year.",
      "rationale": "Effective use of tax credits indicates strong financial management and innovation investment.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Executive Tenure Stability",
      "construction": "Average tenure of the top 5 executives, measured in years, updated annually.",
      "rationale": "Stable management teams may indicate effective leadership and strategic consistency.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Foreign Revenue Growth Ratio",
      "construction": "Percentage change in international sales divided by total revenue growth over the past two years.",
      "rationale": "Growing international presence can diversify revenue streams and reduce domestic market risk.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Intellectual Property Intensity",
      "construction": "Number of active patents divided by total R&D expenditure over the last five years.",
      "rationale": "A higher ratio suggests more efficient R&D processes and a better-protected competitive position.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
